import React, { useState } from "react";

function UseState() {
  const [count, setCount] = useState(0);

  return (
    <div><br /> 
      <h2>Count: {count}</h2>

      <button onClick={() => setCount(count + 1)}>
        Increment (+1)<br/> <br/>
      </button>

      <button onClick={() => setCount(count - 1)}>
       De (-1)
      </button>
    </div>
  );
}

export default UseState;
